    background: rgba(0,0,0,0.5);
    border: none;
    color: #fff;
    font-size: 3rem;
    cursor: pointer;
    z-index: 2;
    transition: background 0.2s;
}

.carousel-nav:hover {
    background: rgba(0,0,0,0.8);
}

.carousel-nav.prev {
    left: -2rem;
}

.carousel-nav.next {
    right: -2rem;
}

@media (max-width: 768px) {
    .carousel-nav {
        display: none;
    }
}

/* Features Section */
.features-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.5rem;
}

@media (min-width: 768px) {
    .features-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (min-width: 1024px) {
    .features-grid {
        grid-template-columns: repeat(4, 1fr);
    }
}

.feature-card {
    background: linear-gradient(135deg, #192247 0%, #210e17 100%);
    border-radius: 1rem;
    padding: 1.5rem;
    position: relative;
    min-height: 250px;
    display: flex;
    flex-direction: column;
}

.feature-card h3 {
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.feature-card p {
    color: rgba(255, 255, 255, 0.7);
    font-size: 1rem;
}

.feature-icon {
    margin-top: auto;
    align-self: flex-end;
    color: #fff;
    width: 48px;
    height: 48px;
    opacity: 0.8;
}

/* FAQ Section */
.faq-accordion {
    max-width: 900px;
    margin: 0 auto 3rem;
}

.faq-item {
    margin-bottom: 0.5rem;
}

.faq-question {
    width: 100%;
    background-color: var(--gray-dark);
    color: #fff;
    border: none;
    padding: 1.5rem;
    font-size: 1.5rem;
    font-weight: 500;
    text-align: left;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    transition: background-color 0.2s;
}

.faq-question:hover {
    background-color: var(--gray-medium);
}

.faq-icon {
    font-size: 2.5rem;
    line-height: 0;
    transition: transform 0.3s ease;
}

.faq-question[aria-expanded="true"] .faq-icon {
    transform: rotate(45deg);
}

.faq-answer {
    background-color: var(--gray-dark);
    padding: 0 1.5rem;
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease, padding 0.3s ease;
    border-top: 1px solid #000;
}

.faq-answer.open {
    max-height: 500px;
    padding: 1.5rem;
}

.faq-answer p {
    margin-bottom: 1rem;
    font-size: 1.25rem;
}

.faq-answer p:last-child {
    margin-bottom: 0;
}

.bottom-cta {
    text-align: center;
    padding: 2rem 0;
}

/* Footer */
.footer {
    padding: 4rem 5%;
    color: var(--gray-light);
    font-size: 0.875rem;
    max-width: 1200px;
    margin: 0 auto;
}

.footer-prompt {
    margin-bottom: 2rem;
}

.footer-prompt a {
    color: var(--gray-light);
}

.footer-links {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 1rem;
    margin-bottom: 2rem;
}

@media (min-width: 768px) {
    .footer-links {
        grid-template-columns: repeat(4, 1fr);
    }
}

.footer-col li {
    margin-bottom: 1rem;
}

.footer-col a {
    color: var(--gray-light);
}

.footer-lang {
    margin-bottom: 1rem;
}

.legal-note {
    font-size: 0.75rem;
    color: var(--gray-light);
}

/* Login Page Styles */
.login-body {
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

.login-bg {
    opacity: 0.5;
}

.login-navbar {
    position: relative;
    background: transparent;
    padding: 1.5rem 5%;
}

.login-main {
    flex-grow: 1;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 2rem 5%;
    z-index: 1;
}

.login-container {
    background-color: rgba(0, 0, 0, 0.7);
    padding: 3rem 4rem;
    border-radius: 4px;
    width: 100%;
    max-width: 450px;
}

.login-title {
    font-size: 2rem;
    margin-bottom: 0.5rem;
}

.login-subtext {
    margin-bottom: 2rem;
    color: var(--gray-light);
}

.login-form .input-wrapper {
    margin-bottom: 1rem;
}

.login-form .btn {
    margin-top: 1.5rem;
}

.help-section {
    margin-top: 1rem;
}

.help-toggle {
    background: none;
    border: none;
    color: var(--gray-light);
    cursor: pointer;
    font-size: 0.875rem;
}

.help-toggle:hover {
    text-decoration: underline;
}

.help-content {
    display: none;
    margin-top: 1rem;
    font-size: 0.875rem;
}

.help-content.open {
    display: block;
}

.help-content p {
    margin-bottom: 0.5rem;
}

.help-content a {
    color: var(--gray-light);
}

.login-footer {
    position: relative;
    background-color: rgba(0, 0, 0, 0.75);
    border-top: 1px solid var(--gray-medium);
    margin: 0;
    max-width: 100%;
    padding: 2rem 5%;
}

@media (max-width: 768px) {
    .login-container {
        padding: 2rem;
        background-color: #000;
    }
    .login-footer {
        background-color: #000;
        border-top: none;
    }
}

